using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class EchoTool
{
    [McpServerTool, Description("Echoes the input message back to the caller.")]
    public static string Echo([Description("The message to echo")] string message)
        => $"Echo: {message}";

    [McpServerTool, Description("Returns the current server time in UTC.")]
    public static string GetServerTime()
        => $"Server time: {DateTime.UtcNow:O}";
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        Uri = "config://app/settings",
        Name = "App Settings",
        Description = "Returns current application configuration data.",
        MimeType = "application/json")]
    public static string GetAppSettings()
    {
        return """
        {
            "environment": "production",
            "version": "1.0.0",
            "features": {
                "darkMode": true,
                "notifications": true,
                "maxRetries": 3
            },
            "endpoints": {
                "api": "https://api.example.com",
                "docs": "https://docs.example.com"
            }
        }
        """;
    }

    [McpServerResource(
        UriTemplate = "config://app/settings/{section}",
        Name = "App Settings Section",
        Description = "Returns a specific section of the application configuration.",
        MimeType = "application/json")]
    public static string GetAppSettingsSection(string section)
    {
        return section.ToLowerInvariant() switch
        {
            "features" => """
            {
                "darkMode": true,
                "notifications": true,
                "maxRetries": 3
            }
            """,
            "endpoints" => """
            {
                "api": "https://api.example.com",
                "docs": "https://docs.example.com"
            }
            """,
            _ => $"""{{ "error": "Unknown section: {section}" }}"""
        };
    }
}

